import {
    Ajax
} from "../../core/utils/ajax";
import {
    isFormData
} from "../../core/utils/ajax_utils";
import jQuery from "jquery";
import useJQueryFn from "./use_jquery";
const useJQuery = useJQueryFn();
if (useJQuery) {
    Ajax.inject({
        sendRequest(options) {
            if (!options.responseType && !options.upload) {
                const settings = isFormData(options.data) ? Object.assign({}, options, {
                    processData: false,
                    contentType: false
                }) : options;
                return jQuery.ajax(settings)
            }
            return this.callBase.apply(this, [options])
        }
    })
}
